INSERT INTO `fsva_indikator_kabupaten` VALUES (1,2024,'Ketersediaan Pangan',1,'Rasio Konsumsi Normatif thd Produksi Bersih Pangan','Rasio','≥ 1.0 (Swasembada)',NULL,'Menunggu Data Integrasi Bapanas / OPD','Distankan KP','Perbandingan produksi bersih beras & jagung terhadap kebutuhan konsumsi normatif penduduk kabupaten.','2026-10-06 08:36:18'),(2,2024,'Ketersediaan Pangan',2,'Rasio Ketersediaan Energi per Kapita / Hari','kkal/kap/hari','≥ 2.100 kkal (Standar WNPG)',NULL,'Menunggu Data Integrasi Bapanas / OPD','Distankan KP','Total ketersediaan kalori pangan dari Neraca Bahan Makanan (NBM) terhadap Angka Kecukupan Energi.','2026-10-06 08:36:18'),(3,2024,'Ketersediaan Pangan',3,'Rasio Ketersediaan Protein Hewani','gram/kap/hari','≥ 14.0 gram protein',NULL,'Menunggu Data Integrasi Bapanas / OPD','Distankan KP','Ketersediaan protein hewani (daging, telur, susu, ikan) terhadap Angka Kecukupan Gizi (AKG).','2026-10-06 08:36:18'),(4,2024,'Ketersediaan Pangan',4,'Rasio Cadangan Beras Pemerintah (CBP)','Ton / % Target','100% Alokasi APBD/Bulog',NULL,'Menunggu Data Integrasi Bapanas / OPD','Bagian Perekonomian Setda & Bulog','Realisasi fisik cadangan beras pemerintah daerah di gudang Bulog dan lumbung pangan masyarakat.','2026-10-06 08:36:18'),(5,2024,'Keterjangkauan Pangan',5,'Persentase Penduduk di Bawah Garis Kemiskinan','%','Makin rendah makin baik',NULL,'Menunggu Data Integrasi Bapanas / OPD','BPS & Dinsos','Proporsi penduduk dengan pengeluaran di bawah garis kemiskinan (data rujukan BPS Banjarnegara).','2026-10-06 08:36:18'),(6,2024,'Keterjangkauan Pangan',6,'Persentase Pengeluaran Pangan (>65% Pengeluaran)','%','< 65% Total Belanja RT',NULL,'Menunggu Data Integrasi Bapanas / OPD','BPS Banjarnegara','Proporsi rumah tangga dengan porsi belanja pangan melebihi 65% dari total pengeluaran konsumsi.','2026-10-06 08:36:18'),(7,2024,'Keterjangkauan Pangan',7,'Rumah Tangga Tanpa Akses Listrik / Jalan Memadai','%','Makin rendah makin baik',NULL,'Menunggu Data Integrasi Bapanas / OPD','DPU PR & Bapperida','Indikator keterisolasian fisik wilayah yang berisiko menghambat kelancaran rantai distribusi pangan pokok.','2026-10-06 08:36:18'),(8,2024,'Keterjangkauan Pangan',8,'Koefisien Variasi Disparitas Harga Pangan Antar Pasar','CV (%)','< 15% (Stabilitas Harga)',NULL,'Menunggu Data Integrasi Bapanas / OPD','Disperindagkop & Distankan KP','Variasi perbedaan harga komoditas pangan pokok strategis antar pasar kecamatan di Banjarnegara.','2026-10-06 08:36:18'),(9,2024,'Pemanfaatan Pangan',9,'Rumah Tangga Tanpa Akses Air Minum Layak','%','Makin rendah makin baik',NULL,'Menunggu Data Integrasi Bapanas / OPD','Dinas Kesehatan & Bapperida','Persentase rumah tangga yang belum memiliki akses sumber air minum terlindungi dan higienis.','2026-10-06 08:36:18'),(10,2024,'Pemanfaatan Pangan',10,'Rasio Tenaga Kesehatan per 10.000 Penduduk','Nakes / 10rb','Standar Kemenkes',NULL,'Menunggu Data Integrasi Bapanas / OPD','Dinas Kesehatan','Ketersediaan dokter umum, bidan, dan perawat pendamping kesehatan & gizi di tingkat puskesmas/desa.','2026-10-06 08:36:18'),(11,2024,'Pemanfaatan Pangan',11,'Prevalensi Balita Stunting (Tinggi Badan menurut Umur)','%','< 14% (Target Nasional)',NULL,'Menunggu Data Integrasi Bapanas / OPD','Dinas Kesehatan (e-PPGBM)','Persentase balita sangat pendek dan pendek berdasarkan hasil penimbangan e-PPGBM Dinas Kesehatan.','2026-10-06 08:36:18'),(12,2024,'Pemanfaatan Pangan',12,'Rumah Tangga Tanpa Sanitasi Layak / Angka Harapan Hidup','% / Tahun','Akses Universal',NULL,'Menunggu Data Integrasi Bapanas / OPD','Dinas Kesehatan & BPS','Cakupan jamban sehat bersertifikasi ODF dan rata-rata angka harapan hidup saat lahir.','2026-10-06 08:36:18');
