DROP TABLE IF EXISTS `horti_produksi_kabupaten`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `horti_produksi_kabupaten` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `kelompok` enum('sayuran_buah_semusim','buah_sayuran_tahunan','tanaman_hias','biofarmaka') NOT NULL,
  `komoditas` varchar(60) NOT NULL,
  `komoditas_id` int(11) DEFAULT NULL,
  `tahun` smallint(5) unsigned NOT NULL,
  `nilai` decimal(14,3) DEFAULT NULL,
  `satuan` enum('ton','tangkai','kg') NOT NULL DEFAULT 'ton',
  `sumber` enum('csv','ckan','manual') NOT NULL DEFAULT 'csv',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_horti_prod_kab` (`kelompok`,`komoditas`,`tahun`),
  KEY `ix_horti_produksi_kabupaten_komoditas_id` (`komoditas_id`)
) ENGINE=InnoDB AUTO_INCREMENT=975 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Produksi hortikultura tingkat kabupaten (file "Menurut Jenis Tanaman")';
